using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
// Candidate assembly only: does not overwrite native prefabs, the user's project, or installed bundle.
public static class NurseIndependentAssembly {
 const string Folder="Assets/EntityStudioGenerated/RebirthNurseIndependentAssembly",Native="Assets/EntityStudioGenerated/RebirthNurseNative",Head="Assets/EntityStudioGenerated/RebirthNurseIndependentHead",Hair="Assets/EntityStudioGenerated/RebirthNurseHairRebuild";
 struct Part{public Mesh mesh;public int source,target;public Part(Mesh m,int s,int t){mesh=m;source=s;target=t;}}
 static Mesh Merge(string name,int slots,params Part[] parts){
  var vertices=new List<Vector3>();var normals=new List<Vector3>();var coords=new List<Vector2>();var weights=new List<BoneWeight>();var triangles=Enumerable.Range(0,slots).Select(_=>new List<int>()).ToArray();var poses=parts[0].mesh.bindposes;
  foreach(var part in parts){var mesh=part.mesh;if(mesh.bindposes.Length!=poses.Length)throw new Exception("Bind layout mismatch");for(int i=0;i<poses.Length;i++)for(int a=0;a<16;a++)if(Mathf.Abs(mesh.bindposes[i][a]-poses[i][a])>.00001f)throw new Exception("Bind matrix mismatch");var p=mesh.vertices;var n=mesh.normals;var uv=mesh.uv;var bw=mesh.boneWeights;var ids=new Dictionary<int,int>();foreach(int source in mesh.GetTriangles(part.source)){int target;if(!ids.TryGetValue(source,out target)){target=vertices.Count;ids[source]=target;vertices.Add(p[source]);normals.Add(n[source]);coords.Add(uv[source]);weights.Add(bw[source]);}triangles[part.target].Add(target);}}
  var result=new Mesh{name=name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,vertices=vertices.ToArray(),normals=normals.ToArray(),uv=coords.ToArray(),boneWeights=weights.ToArray(),bindposes=poses,subMeshCount=slots};for(int i=0;i<slots;i++)result.SetTriangles(triangles[i],i);result.RecalculateTangents();result.RecalculateBounds();foreach(var w in weights)if(Mathf.Abs(w.weight0+w.weight1+w.weight2+w.weight3-1)>.001f)throw new Exception("Non-unit candidate weight");return result;
 }
 static T Save<T>(T value,string path)where T:UnityEngine.Object{var previous=AssetDatabase.LoadAssetAtPath<T>(path);if(previous==null){AssetDatabase.CreateAsset(value,path);AssetDatabase.SaveAssetIfDirty(value);return value;}if(value is Mesh source&&previous is Mesh target){target.Clear();target.indexFormat=source.indexFormat;target.vertices=source.vertices;target.normals=source.normals;target.uv=source.uv;target.boneWeights=source.boneWeights;target.bindposes=source.bindposes;target.subMeshCount=source.subMeshCount;for(int i=0;i<source.subMeshCount;i++)target.SetTriangles(source.GetTriangles(i),i);target.RecalculateTangents();target.RecalculateBounds();}else EditorUtility.CopySerialized(value,previous);EditorUtility.SetDirty(previous);AssetDatabase.SaveAssetIfDirty(previous);return previous;}
 public static void RepairEyeAsset(){try{Save(Merge("RebirthNurse_Independent_Eyes",1,new Part(AssetDatabase.LoadAssetAtPath<Mesh>(Head+"/Head_LOD0.asset"),1,0)),Folder+"/Eyes.asset");AssetDatabase.ImportAsset(Folder+"/Eyes.asset",ImportAssetOptions.ForceSynchronousImport);var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Eyes.asset");float mean=mesh.GetTriangles(0).Average(id=>mesh.uv[id].y);if(Mathf.Abs(mean-(1.628f-1.44f)/.305f)>.0001f)throw new Exception("Saved eye UV layout did not persist");EyeDiagnosis();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static Material HeadMaterial(){var material=new Material(AssetDatabase.LoadAssetAtPath<Material>(Head+"/EntityStudioHead_RebirthNurse_Normal.mat"));material.name="EntityStudioHead_RebirthNurse_Normal";material.shader=AssetDatabase.LoadAssetAtPath<Material>("Assets/NativeReferences/Moe/Material/HD_Moe.mat").shader;return Save(material,Folder+"/Head_Normal.mat");}
 static string RigSignature(GameObject go){Func<Transform,string> path=t=>AnimationUtility.CalculateTransformPath(t,go.transform);var rows=new List<string>();foreach(var t in go.GetComponentsInChildren<Transform>(true))rows.Add(path(t)+"|"+t.localPosition.ToString("R")+"|"+t.localRotation.ToString("R")+"|"+t.localScale.ToString("R")+"|"+t.tag+"|"+t.gameObject.layer);foreach(var c in go.GetComponentsInChildren<CapsuleCollider>(true))rows.Add("capsule|"+path(c.transform)+"|"+c.center.ToString("R")+"|"+c.radius+"|"+c.height+"|"+c.direction+"|"+c.isTrigger+"|"+c.enabled);foreach(var r in go.GetComponentsInChildren<Rigidbody>(true))rows.Add("body|"+path(r.transform)+"|"+r.mass+"|"+r.drag+"|"+r.angularDrag+"|"+r.isKinematic+"|"+r.useGravity+"|"+r.constraints);foreach(var j in go.GetComponentsInChildren<CharacterJoint>(true))rows.Add("joint|"+path(j.transform)+"|"+(j.connectedBody?path(j.connectedBody.transform):"")+"|"+j.anchor.ToString("R")+"|"+j.connectedAnchor.ToString("R")+"|"+j.axis.ToString("R")+"|"+j.swingAxis.ToString("R")+"|"+j.lowTwistLimit.limit+"|"+j.highTwistLimit.limit+"|"+j.swing1Limit.limit+"|"+j.swing2Limit.limit);return String.Join("\n",rows.OrderBy(s=>s));}
 public static void PrepareAndReview(){Prepare();Review();}
 public static void ReconstructAndCompare(){PrepareAndReview();RefreshMoeReference();}
 public static void RefreshMoeReference(){try{foreach(int angle in new[]{0,-30,30}){UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);var moe=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));moe.GetComponent<Animator>().enabled=false;moe.GetComponent<LODGroup>().ForceLOD(0);moe.transform.RotateAround(new Vector3(0,1.72f,0),Vector3.up,angle);NurseVisualOptimization.Render(moe,"MoeFace_Quality_"+angle,0,true);var a=new Texture2D(2,2);a.LoadImage(File.ReadAllBytes(NurseVisualOptimization.Out+"/MoeFace_Quality_"+angle+".png"));var b=new Texture2D(2,2);b.LoadImage(File.ReadAllBytes(NurseVisualOptimization.Out+"/AssembledIndependent_Face_"+angle+".png"));var pair=new Texture2D(a.width+b.width,a.height,TextureFormat.RGB24,false);pair.SetPixels(0,0,a.width,a.height,a.GetPixels());pair.SetPixels(a.width,0,b.width,b.height,b.GetPixels());pair.Apply();File.WriteAllBytes(NurseVisualOptimization.Out+"/AssembledIndependent_Moe_Comparison_"+angle+".png",pair.EncodeToPNG());}Debug.Log("NURSE_INDEPENDENT_COMPARISON_REFRESHED");}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void PersistenceAudit(){try{var rows=new List<string>();for(int lod=0;lod<3;lod++){var assembled=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/LOD"+lod+".asset");var source=AssetDatabase.LoadAssetAtPath<Mesh>(Head+"/Head_LOD"+lod+".asset");var a=assembled.GetTriangles(2);var b=source.GetTriangles(0);if(!a.Select(i=>assembled.uv[i]).SequenceEqual(b.Select(i=>source.uv[i]))||!a.Select(i=>assembled.vertices[i]).SequenceEqual(b.Select(i=>source.vertices[i])))throw new Exception("Persisted head geometry/UV mismatch at LOD"+lod);rows.Add("Reloaded LOD"+lod+" independent head position/UV triangle streams exactly match the authored head asset; combined triangles="+assembled.triangles.Length/3);}var eyes=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Eyes.asset");var head=AssetDatabase.LoadAssetAtPath<Mesh>(Head+"/Head_LOD0.asset");if(!eyes.GetTriangles(0).Select(i=>eyes.uv[i]).SequenceEqual(head.GetTriangles(1).Select(i=>head.uv[i])))throw new Exception("Persisted independent eye UV mismatch");rows.Add("Reloaded eyes match current head eye UV stream; eye triangles="+eyes.triangles.Length/3);File.WriteAllLines(NurseVisualOptimization.Out+"/independent-mesh-persistence.txt",rows);Debug.Log("NURSE_INDEPENDENT_MESH_PERSISTENCE_READY");}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void EyeDiagnosis(){try{UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/RebirthNurse_IndependentCandidate.prefab"));model.GetComponent<Animator>().enabled=false;model.GetComponent<LODGroup>().ForceLOD(0);RebirthEntityStudio.RebirthNurseNativeShaderPreview.Bind(model);var rows=new List<string>();foreach(var eye in model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.name=="NormalEye")){var world=NurseAnatomyRender.WorldSkin(eye);var v=world.vertices;var uv=eye.sharedMesh.uv;int front=Enumerable.Range(0,v.Length).Where(i=>v[i].x<0).OrderByDescending(i=>v[i].z).First();foreach(string meshPath in new[]{Folder+"/Eyes.asset",Head+"/Head_LOD0.asset"}){var asset=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);var ids=asset.GetTriangles(meshPath.Contains("Head_LOD")?1:0);rows.Add(meshPath+" eyeUV average="+ids.Average(id=>asset.uv[id].y));}rows.Add("Eye mesh="+AssetDatabase.GetAssetPath(eye.sharedMesh));rows.Add("NormalEye enabled="+eye.enabled+" active="+eye.gameObject.activeInHierarchy+" world="+v[front].ToString("R")+" uv="+uv[front].ToString("R")+" material="+eye.sharedMaterial.name+" albedo="+AssetDatabase.GetAssetPath(eye.sharedMaterial.GetTexture("_Albedo")));var explicitMaterial=new Material(AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Head_Normal.mat"));explicitMaterial.shader=RebirthEntityStudio.RebirthNativeShaderLibrary.Get("Game/Character");eye.sharedMaterial=explicitMaterial;eye.enabled=true;eye.gameObject.SetActive(true);}NurseVisualOptimization.Render(model,"IndependentEye_ExplicitMaterial",0,true,true);File.WriteAllLines(NurseVisualOptimization.Out+"/independent-eye-diagnosis.txt",rows);Debug.Log("NURSE_INDEPENDENT_EYE_DIAGNOSIS_READY");}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void NativePoseComparison(){try{UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));model.name="Moe_AnimationReference";var animator=model.GetComponent<Animator>();animator.enabled=false;model.GetComponent<LODGroup>().ForceLOD(0);var rows=new List<string>();foreach(string category in new[]{"walkForward","melee","Pain"}){var clip=animator.runtimeAnimatorController.animationClips.First(c=>c.name.StartsWith(category,StringComparison.OrdinalIgnoreCase)&&c.length>.2f);AnimationMode.StartAnimationMode();try{AnimationMode.BeginSampling();AnimationMode.SampleAnimationClip(model,clip,clip.length*.4f);AnimationMode.EndSampling();NurseVisualOptimization.Render(model,"NativeMoe_Pose_"+category,0,false);rows.Add(category+"="+clip.name+" at 40% of clip");}finally{AnimationMode.StopAnimationMode();}}File.WriteAllLines(NurseVisualOptimization.Out+"/native-pose-comparison.txt",rows);Debug.Log("NURSE_NATIVE_POSE_COMPARISON_READY");}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void Review(){try{UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);var rows=new List<string>();var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/RebirthNurse_IndependentCandidate.prefab"));var animator=model.GetComponent<Animator>();animator.enabled=false;model.GetComponent<LODGroup>().ForceLOD(0);var body=model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");
  for(int lod=0;lod<3;lod++){body.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/LOD"+lod+".asset");NurseVisualOptimization.Render(model,"AssembledIndependent_LOD"+lod,0,false);}body.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/LOD0.asset");foreach(int angle in new[]{0,-30,30}){model.transform.rotation=Quaternion.Euler(0,angle,0);NurseVisualOptimization.Render(model,"AssembledIndependent_Face_"+angle,0,true);}model.transform.rotation=Quaternion.identity;
  var baseline=NurseAnatomyRender.WorldSkin(body).vertices;var hairRoot=body.bones.Single(b=>b.name=="Hair_Back_Left");var rotation=hairRoot.localRotation;hairRoot.localRotation*=Quaternion.Euler(4,4,0);var moved=NurseAnatomyRender.WorldSkin(body).vertices;float nonHair=0,maximum=0;int moving=0;var hairIds=new HashSet<int>(body.sharedMesh.GetTriangles(1));for(int i=0;i<moved.Length;i++){float distance=Vector3.Distance(moved[i],baseline[i]);if(hairIds.Contains(i)){maximum=Mathf.Max(maximum,distance);if(distance>.0001f)moving++;}else nonHair=Mathf.Max(nonHair,distance);}if(nonHair>.00001f||maximum<.0001f)throw new Exception("Candidate hair influence escaped or did not move: nonHair="+nonHair+"m; hair="+maximum+"m; moving="+moving);NurseVisualOptimization.Render(model,"AssembledIndependent_HairSway",0,true);hairRoot.localRotation=rotation;rows.Add("Controlled hair-chain rotation 4 degrees X/Y: moving hair vertices="+moving+" max displacement="+maximum+"m; max body/head displacement="+nonHair+"m. Editor deformation evidence, not gameplay.");
  foreach(string category in new[]{"walkForward","melee","Pain"}){var clip=animator.runtimeAnimatorController.animationClips.First(c=>c.name.StartsWith(category,StringComparison.OrdinalIgnoreCase)&&c.length>.2f);AnimationMode.StartAnimationMode();try{AnimationMode.BeginSampling();AnimationMode.SampleAnimationClip(model,clip,clip.length*.4f);AnimationMode.EndSampling();var surface=NurseAnatomyRender.WorldSkin(body);if(surface.vertices.Any(v=>float.IsNaN(v.x)||float.IsInfinity(v.x)))throw new Exception("Nonfinite animated skin");NurseVisualOptimization.Render(model,"AssembledIndependent_Pose_"+category,0,false);rows.Add("Sampled native clip "+clip.name+": finite deformed geometry.");}finally{AnimationMode.StopAnimationMode();}}
  File.WriteAllLines(NurseVisualOptimization.Out+"/independent-assembly-animation.txt",rows);Debug.Log("NURSE_INDEPENDENT_ASSEMBLY_REVIEW_READY");}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void Prepare(){try{
  Directory.CreateDirectory(Folder);var lods=new Mesh[3];Mesh eyes=null;var rows=new List<string>();GameObject model=null;var original=AssetDatabase.LoadAssetAtPath<GameObject>(Native+"/RebirthNurse_Authoring.prefab");string rigBefore=RigSignature(original);
  for(int lod=0;lod<3;lod++){var go=NurseIndependentHead.BuildPreview(lod,lod==0);var renderers=go.GetComponentsInChildren<SkinnedMeshRenderer>(true);var body=renderers.Single(r=>r.name=="LOD0");var support=renderers.Single(r=>r.name=="ConcealedGarmentSupport");var hair=renderers.Single(r=>r.name=="RebuiltHairPreview");var head=renderers.Single(r=>r.name=="IndependentFemaleHeadPreview");
   lods[lod]=Save(Merge("RebirthNurse_Independent_LOD"+lod,3,new Part(body.sharedMesh,0,0),new Part(support.sharedMesh,0,0),new Part(hair.sharedMesh,0,1),new Part(head.sharedMesh,0,2)),Folder+"/LOD"+lod+".asset");if(lod==0)eyes=Save(Merge("RebirthNurse_Independent_Eyes",1,new Part(head.sharedMesh,1,0)),Folder+"/Eyes.asset");rows.Add("LOD"+lod+" body/hair/head="+String.Join("/",Enumerable.Range(0,3).Select(s=>lods[lod].GetTriangles(s).Length/3))+" triangles; normalized weights; bindposes="+lods[lod].bindposes.Length);model=go;
  }
  model.name="RebirthNurse_IndependentCandidate";var all=model.GetComponentsInChildren<SkinnedMeshRenderer>(true);var main=all.Single(r=>r.name=="LOD0");var headMat=HeadMaterial();var bodyMaterial=AssetDatabase.FindAssets("t:Material",new[]{Native}).Select(g=>AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(g))).Single(m=>m.name.Contains("_Normal_Slot0"));var hairMat=new Material(AssetDatabase.LoadAssetAtPath<Material>(Hair+"/Hair.mat"));hairMat.shader=AssetDatabase.LoadAssetAtPath<Material>("Assets/NativeReferences/Moe/Material/HD_MoeHair.mat").shader;hairMat=Save(hairMat,Folder+"/Hair_Normal.mat");
  foreach(var renderer in all){if(renderer.name.StartsWith("LOD")&&renderer.name.Length==4){int lod=renderer.name[3]-'0';if(lod>=0&&lod<3){renderer.sharedMesh=lods[lod];renderer.sharedMaterials=new[]{bodyMaterial,hairMat,headMat};}}if(renderer.name=="NormalEye"||renderer.name=="FeralEye"){renderer.sharedMesh=eyes;renderer.bones=main.bones;renderer.rootBone=main.rootBone;renderer.sharedMaterials=new[]{headMat};renderer.enabled=renderer.name=="NormalEye";renderer.gameObject.SetActive(renderer.name=="NormalEye");}}
  foreach(string name in new[]{"IndependentFemaleHeadPreview","RebuiltHairPreview","ConcealedGarmentSupport"})UnityEngine.Object.DestroyImmediate(model.GetComponentsInChildren<Transform>(true).Single(t=>t.name==name).gameObject);
  if(model.GetComponentsInChildren<Rigidbody>(true).Length!=11||model.GetComponentsInChildren<CharacterJoint>(true).Length!=10||model.GetComponentsInChildren<CapsuleCollider>(true).Length!=12)throw new Exception("Candidate physics changed");
  if(RigSignature(model)!=rigBefore)throw new Exception("Candidate changed native rig transforms, tags or physics fields");rows.Add("Native transform/tag/layer, capsule dimensions, rigidbody settings, joint anchors/axes/limits signature unchanged.");
  PrefabUtility.SaveAsPrefabAsset(model,Folder+"/RebirthNurse_IndependentCandidate.prefab");AssetDatabase.SaveAssets();rows.Add("Existing native tagged NormalEye/FeralEye objects reused with independent eye geometry; original bone list retained. Candidate only: tier workspace/variant export and installation not complete.");File.WriteAllLines(NurseVisualOptimization.Out+"/independent-assembly-proof.txt",rows);Debug.Log("NURSE_INDEPENDENT_CANDIDATE_ASSEMBLED");
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
